def stoneGameII(piles):
    n = len(piles)
    # suffix_sum[i]: total stones from i to end
    suffix_sum = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_sum[i] = piles[i] + suffix_sum[i + 1]

    from functools import lru_cache

    # dp(i, m): max stones Alice can get starting from pile i with current M=m
    @lru_cache(maxsize=None)
    def dp(i, m):
        if i >= n:
            return 0
        max_stones = 0
        # Try taking X piles, X in 1..min(2 * m, n-i)
        for x in range(1, min(2 * m, n - i) + 1):
            # Current player takes suffix_sum[i] - suffix_sum[i + x] now; the opponent
            # then plays optimally from i + x with M = max(m, x). What the current
            # player ends with is the whole remaining pile minus the opponent's best.
            max_stones = max(max_stones, suffix_sum[i] - dp(i + x, max(m, x)))
        return max_stones

    return dp(0, 1)
